const pick = (o) => o[i18n.current()] || o.en || o.ko;
export function titleOf(n) { return pick(n.title); }
export function itemsOf(n) { return pick(n.items); }
/* 앱 버전(versionCode)에 따라 보이는 공지 (2026-11-01): minNative 가 붙은 공지는 그 버전 이상 앱에만 — 패치만 받은 옛 앱에 없는 기능을 알리지 않게 */
let nativeBuild = Infinity;                        // 웹·확인 전에는 모두 보인다
async function loadNative() {
  try { const A = window.Capacitor?.isNativePlatform?.() ? window.Capacitor?.Plugins?.App : null; if (A?.getInfo) { const i = await A.getInfo(); const b = +i.build; if (Number.isFinite(b) && b > 0) nativeBuild = b; } } catch { /* 그대로 */ }
}
/* minNative 는 안드로이드 versionCode 기준 — 아이폰은 빌드 번호 체계가 달라, 안드로이드 앱 버전에 묶인 공지(중요 알림 등 안드로이드 전용)는 아이폰에서 숨긴다 (2026-11-01) */
const isIOS = () => { try { return window.Capacitor?.getPlatform?.() === 'ios'; } catch { return false; } };
export function visible() { return NOTICES.filter((n) => !n.minNative || (!isIOS() && nativeBuild >= n.minNative)); }
export function latest() { return visible()[0]; }

let seen = null;                                   // 메모리 사본 (홈을 그릴 때 동기로 본다)
export async function load() { await loadNative(); seen = await store.metaGet('noticeSeen', null); return seen; }
export function hasUnread() { return seen !== latest().id; }
export async function markRead() { seen = latest().id; await store.metaSet('noticeSeen', seen); }

/** 날짜 표기 (앱 언어로) */
export function dateOf(n) {
  try {
    const [y, m, d] = n.date.split('-').map(Number);
    return new Intl.DateTimeFormat(i18n.locale(), { year: 'numeric', month: 'long', day: 'numeric' }).format(new Date(y, m - 1, d));
  } catch { return n.date; }
}
